def rot(g): return [list(r) for r in zip(*g[::-1])]
def variants(g):
    r=g; out=[]
    for _ in range(4):
        out.append(r)
        out.append([row[::-1] for row in r])
        r=rot(r)
    return out
def sym_score(g):
    bad={'90':0,'180':0,'tr':0}
    for i in range(16):
        for j in range(16):
            a=g[i][j]
            if a!=g[j][15-i]: bad['90']+=1
            if a!=g[15-i][15-j]: bad['180']+=1
            if a!=g[j][i]: bad['tr']+=1
    return bad
